function YieldReview(){
 const [country,setCountry]=useState('brazil');
 const d=YIELD_RESULTS[country], names={brazil:'Brazil',argentina:'Argentina',usa:'United States'};
 const plot={left:48,top:18,width:324,height:220,max:6};
 const sx=v=>plot.left+v/plot.max*plot.width, sy=v=>plot.top+plot.height-v/plot.max*plot.height;
 return <section className="yieldreview" id="yield-review">
  <div className="secttl">Separate research experiment</div>
  <h2>Can satellites estimate regional yield?</h2>
  <p className="yieldlead">Historical soybean yield estimation, not a forecast for these farms.</p>
  <p>Trained on 2005-2013, tested on 2014-2016 using the full season's MODIS record. Results are mixed: Brazil and the US beat local history modestly; Argentina does worse.</p>
  <div className="yieldtabs" role="group" aria-label="Evaluation country">{Object.entries(names).map(([k,v])=><button key={k} className={country===k?'active':''} onClick={()=>setCountry(k)}>{v}</button>)}</div>
  <h3>{names[country]} · {d.n.toLocaleString()} held-out region-years</h3>
  <div className="yieldverdict">{d.model<d.history?'Lower error than local history in this test.':'Worse than local history in this test.'} Not validated for a current season.</div>
  <div className="yieldmetrics"><span><small>Ridge model</small><b>{d.model.toFixed(3)}</b></span><span><small>Local history</small><b>{d.history.toFixed(3)}</b></span><span><small>Global mean</small><b>{d.mean.toFixed(3)}</b></span></div>
  <p className="yieldcaption">RMSE, tonnes per harvested hectare. Lower is better. Local history uses each region's training-years mean. Model R²: {d.r2.toFixed(3)}.</p>
  <svg className="yieldplot" viewBox="0 0 400 292" role="img" aria-label={`${names[country]} held-out actual versus estimated soybean yields in tonnes per hectare`}>
   {[0,1,2,3,4,5,6].map(t=><g key={t}><line x1={sx(t)} y1={sy(0)} x2={sx(t)} y2={sy(6)} stroke="#263326"/><line x1={sx(0)} y1={sy(t)} x2={sx(6)} y2={sy(t)} stroke="#263326"/><text x={sx(t)} y={255} textAnchor="middle">{t}</text><text x={35} y={sy(t)+4} textAnchor="end">{t}</text></g>)}
   <line x1={sx(0)} y1={sy(0)} x2={sx(6)} y2={sy(6)} stroke="#becab4" strokeDasharray="4 4"/>
   {d.points.map(([r,y,a,p],i)=><circle key={i} cx={sx(a)} cy={sy(p)} r={country==='usa'?2:3} fill="#a3d98b" opacity=".52"><title>{r}, {y}: actual {a}, model {p} t/ha</title></circle>)}
   <text x="210" y="282" textAnchor="middle">Reported yield (t/ha)</text><text transform="translate(13 130) rotate(-90)" textAnchor="middle">Model estimate (t/ha)</text>
  </svg>
  <p className="yieldcaption">Each dot is one region-year, not one farm. Dashed diagonal = exact agreement. Hover a point for its region and year.</p>
  <details><summary>Method, sources and limits</summary>
   <p>SustainBench Crop Yield v1.0, based on Wang et al. (2018): reported regional soybean yields and MODIS spectral/temperature histograms plus seasonal NDVI. Ridge regression uses 326 features. Tuning uses training data only. Baselines and failures are shown, not hidden.</p>
   <p>All inputs span the whole harvest season. This is retrospective estimation, not advance warning. An additional held-out-region test shares 2005-2016 on both sides: Argentina and the US show signal, Brazil does not. It does not establish future-year reliability. Exploratory bad-season analysis is not a validated alert.</p>
   <p>No model output is attached to our 24 parcels. Different sensors, crop assumptions, geography and aggregation prevent a direct mapping. No weather features or repayment labels were used, and this is not a loan-default model.</p>
   <p>Dataset and derivative evaluation: <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Credit: SustainBench / Stanford Sustainability and AI Lab, NASA MODIS inputs, underlying government yield statistics; Wang et al. (2018). SustainBench code is MIT.</p>
   <a href="https://sustainlab-group.github.io/sustainbench/docs/datasets/sdg2/crop_yield.html" target="_blank" rel="noopener">Dataset documentation</a> · <a href="https://doi.org/10.1145/3209811.3212707" target="_blank" rel="noopener">Original study</a>
  </details>
 </section>;
}


/* ---------- scenario transforms ---------- */
function readings(loan, scenario){
  let a = loan.rain_anomaly_pct, soil = loan.soil_moisture, sat = loan.s2, missing = false;
  if (scenario === 'drought'){ a = a - 38; soil = soil * 0.65; }
  if (scenario === 'rain'){ a = a + 65; soil = Math.min(soil * 1.35, 0.6); }
  if (scenario === 'heat'){ soil = soil * 0.75; }
  if (scenario === 'missing'){
    const n = parseInt(loan.loan_id.slice(3), 10);
    if (n % 3 === 0){ missing = true; }
  }
  a = Math.round(a);
  /* Simulated rain amount derived from the same baseline the anomaly % uses,
     so displayed mm, % and ranking always agree. Live shows the real measurement. */
  const rain = scenario === 'live'
    ? loan.rain_60d_mm
    : Math.round(loan.rain_hist_mm * (1 + a / 100) * 10) / 10;
  return { a, soil, sat, missing, rain };
}

function flagFor(r){
  if (r.missing) return { level:'grey', label:'No current data', sort: 95 };
  let level = 'green', label = 'Rain near seasonal norm';
  if (r.a <= -25){ level='red'; label='Rain well below normal'; }
  else if (r.a >= 30){ level='red'; label='Rain far above normal'; }
  else if (r.a <= -15 || r.a >= 20){ level='amber'; label = r.a < 0 ? 'Rain below normal' : 'Rain above normal'; }
  const sort = Math.abs(r.a);
  return { level, label, sort };
}

function fmtRain(l, r){ return `${r.rain} mm in 60 days vs ${l.rain_hist_mm} mm typical`; }
function ageOf(dateStr){
  return Math.round((new Date('2026-11-10') - new Date(dateStr)) / 86400000);
}

const COLORS = { red:'#e8836f', amber:'#e4b272', green:'#a3d98b', grey:'#8a938a' };
const SCENARIOS = [
  ['live', 'Nov 8 snapshot', 'measured data'],
  ['drought', 'Drought', 'simulated dry spell'],
  ['rain', 'Heavy rain', 'simulated wet spell'],
  ['heat', 'Heat wave', 'simulated hot spell'],
  ['missing', 'Missing data', 'simulated feed outage'],
];

